<?php

namespace Database\Seeders;

use App\Actions\Teams\CreateTeam;
use App\Enums\UserRole;
use App\Models\Organization;
use App\Models\ShopBranch;
use App\Models\ShopHeadquarter;
use App\Models\User;
use App\Models\WarehouseBranch;
use App\Models\WarehouseHeadquarter;
use Illuminate\Database\Seeder;

class OrganizationSeeder extends Seeder
{
    /**
     * Demo organization with the full layout: organization → headquarters → branches → workers,
     * one person per role, separately for the shop and the warehouse. Password of all accounts: qwer1234.
     *
     * Barcodes are generated by the models ("created" event), so model events must not be disabled.
     * The seeder can be run repeatedly: existing records are kept.
     */
    public function run(): void
    {
        $address = [
            'street' => 'ROZTOKI',
            'building_number' => '43',
            'postal_code' => '38-204',
            'city' => 'ROZTOKI',
            'country' => 'PL',
        ];

        $organization = Organization::firstOrCreate(['NIP' => '6852339117'], [
            'name' => 'jan nowak',
            'REGON' => '384905278',
            'email' => 'organizacja1@example.pl',
            ...$address,
        ]);
        $org = ['organization_id' => $organization->id];

        $this->user('organizacja1@example.pl', 'jan', UserRole::ORGANIZATION_OWNER, '+48600000001', $org);

        // ----- shop: headquarters, branch and their people
        $shop = $organization->shopHeadquarters()->firstOrCreate(['name' => 'ALEKSANDER GAZDA'], [
            'NIP' => '6852339117',
            'email' => 'test@sklephead.pl',
            'phone' => '234234234',
            ...$address,
        ]);
        $shopBranch = ShopBranch::firstOrCreate(
            ['shop_headquarter_id' => $shop->id, 'name' => 'Sklep - placówka 1'],
            ['organization_id' => $organization->id, 'NIP' => '6852339117', ...$address],
        );
        $shopLinks = [...$org, 'shop_headquarter_id' => $shop->id];

        $this->user('test@sklephead.pl', 'sklep1', UserRole::SHOP_OWNER, '+48600000002', $shopLinks);
        $this->user('sklep.lider1@example.pl', 'Sklep lider 1', UserRole::SHOP_LEADER, '+48600000003', [...$shopLinks, 'shop_branch_id' => $shopBranch->id]);
        $this->user('sklep.pracownik1@example.pl', 'Sklep pracownik 1', UserRole::SHOP_WORKER, '+48600000004', [...$shopLinks, 'shop_branch_id' => $shopBranch->id]);

        // ----- warehouse: headquarters, branch and their people
        $warehouse = $organization->warehouseHeadquarters()->firstOrCreate(['name' => 'Hurtownia główna'], [
            'NIP' => '6852339117',
            'email' => 'hurtownia1@example.pl',
            ...$address,
        ]);
        $warehouseBranch = WarehouseBranch::firstOrCreate(
            ['warehouse_headquarter_id' => $warehouse->id, 'name' => 'Magazyn - placówka 1'],
            ['organization_id' => $organization->id, 'NIP' => '6852339117', ...$address],
        );
        $warehouseLinks = [...$org, 'warehouse_headquarter_id' => $warehouse->id];

        $this->user('magazyn.kierownik1@example.pl', 'Magazyn kierownik 1', UserRole::WAREHOUSE_OWNER, '+48600000005', $warehouseLinks);
        $this->user('magazyn.lider1@example.pl', 'Magazyn lider 1', UserRole::WAREHOUSE_LEADER, '+48600000006', [...$warehouseLinks, 'warehouse_branch_id' => $warehouseBranch->id]);
        $this->user('magazyn.pracownik1@example.pl', 'Magazyn pracownik 1', UserRole::WAREHOUSE_WORKER, '+48600000007', [...$warehouseLinks, 'warehouse_branch_id' => $warehouseBranch->id]);
    }

    /**
     * @param  array<string, mixed>  $attributes
     */
    private function user(string $email, string $name, UserRole $role, string $phone, array $attributes): void
    {
        if (User::where('email', $email)->exists()) {
            return;
        }

        $user = User::create([
            'name' => $name,
            'email' => $email,
            'phone' => $phone,
            'password' => 'qwer1234', // haszowane przez cast "hashed"
            'role' => $role,
            ...$attributes,
        ]);

        $user->forceFill(['email_verified_at' => now()])->save();

        app(CreateTeam::class)->handle($user, $user->name."'s Team", isPersonal: true);
    }
}
